// @FIGURE_CODE_BEGIN
// near end parabolic cross-section outline → Line sampled from y(x) at Z=0, black
// far end parabolic cross-section outline → Line sampled from y(x) at Z=12L, black
// top-width chords at both ends → Line segments across x=-6..6 at y=18, black
// upper rim edges connecting ends → Line segments at x=±6, y=18, black
// bottom longitudinal seam/generator → Line from parabola vertex to far vertex, black
// thin wireframe side surface → wireframe Mesh sampled as the cross-section extruded along Z, pale black
// open top rectangle → four black rim/chord line segments
// 18 in dimension arrow → vertical Line plus two ConeGeometry arrowheads inside near face
// far 12 in dimension segment → bracket Line above far top chord, black
// water fill chords → dark blue Lines at y=h on near and far cross-sections
// water surface → translucent pale-blue rectangular Mesh spanning between fill chords
// graph x-axis → black Line with small cone arrowhead
// graph y-axis → black Line with small cone arrowhead
// graph parabolic curve → plotCurve3D handle sampled from equation input
// graph water-depth line → horizontal blue Line at selected h
// graph chord-width bracket → blue Line with tick marks between intersections
// graph rim endpoint markers → two small black SphereGeometry points at (-6,18) and (6,18)

const SCALE_IN = 0.1;
const OUTLINE = 0x111111;
const WATER = 0x4da3ff;
const WATER_DARK = 0x1f77cc;

const troughGroup = new THREE.Group();
troughGroup.name = '3D parabolic trough';
troughGroup.scale.setScalar(SCALE_IN);

const graphGroup = new THREE.Group();
graphGroup.name = 'cross-section graph';
graphGroup.scale.setScalar(SCALE_IN);

scene.add(troughGroup);

const matBlack = new THREE.LineBasicMaterial({ color: OUTLINE });
const matDim = new THREE.LineBasicMaterial({ color: OUTLINE });
const matWaterLine = new THREE.LineBasicMaterial({ color: WATER_DARK });
const matGraphWater = new THREE.LineBasicMaterial({ color: WATER_DARK });
const matWire = new THREE.MeshBasicMaterial({
  color: OUTLINE,
  wireframe: true,
  transparent: true,
  opacity: 0.16,
  side: THREE.DoubleSide
});
const matWaterSurface = new THREE.MeshBasicMaterial({
  color: WATER,
  transparent: true,
  opacity: 0.28,
  side: THREE.DoubleSide,
  depthWrite: false
});
const matPoint = new THREE.MeshBasicMaterial({ color: OUTLINE });
const matCone = new THREE.MeshBasicMaterial({ color: OUTLINE });

function makeLine(parent, material, name) {
  const line = new THREE.Line(new THREE.BufferGeometry(), material);
  line.name = name || 'line';
  parent.add(line);
  return line;
}

function setLinePoints(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old?.dispose?.();
  line.visible = pts.length >= 2;
}

function localPoint(x, y, z = 0) {
  return new THREE.Vector3(x, y, z);
}

function worldPoint(x, y, z = 0) {
  return new THREE.Vector3(x * SCALE_IN, y * SCALE_IN, z * SCALE_IN);
}

function fmt(n, digits = 2) {
  if (!Number.isFinite(n)) return '—';
  const s = Number(n).toFixed(digits);
  return s.replace(/\.?0+$/, '');
}

const nearProfileLine = makeLine(troughGroup, matBlack, 'near parabolic end');
const farProfileLine = makeLine(troughGroup, matBlack, 'far parabolic end');
const nearTopChordLine = makeLine(troughGroup, matBlack, 'near top chord');
const farTopChordLine = makeLine(troughGroup, matBlack, 'far top chord');
const leftRimLine = makeLine(troughGroup, matBlack, 'left upper rim');
const rightRimLine = makeLine(troughGroup, matBlack, 'right upper rim');
const bottomSeamLine = makeLine(troughGroup, matBlack, 'bottom longitudinal seam');
const farWidthBracketLine = makeLine(troughGroup, matDim, '12 inch far width bracket');
const waterNearChordLine = makeLine(troughGroup, matWaterLine, 'near water chord');
const waterFarChordLine = makeLine(troughGroup, matWaterLine, 'far water chord');

const troughWireMesh = new THREE.Mesh(new THREE.BufferGeometry(), matWire);
troughWireMesh.name = 'wireframe extruded parabolic side surface';
troughGroup.add(troughWireMesh);

const waterSurfaceMesh = new THREE.Mesh(new THREE.BufferGeometry(), matWaterSurface);
waterSurfaceMesh.name = 'water surface rectangle';
troughGroup.add(waterSurfaceMesh);

const depthArrowLine = makeLine(troughGroup, matDim, '18 inch depth arrow');
setLinePoints(depthArrowLine, [localPoint(-3.6, 0.45, -0.15), localPoint(-3.6, 17.55, -0.15)]);
const topArrow = new THREE.Mesh(new THREE.ConeGeometry(0.32, 0.9, 24), matCone);
topArrow.position.set(-3.6, 17.55, -0.15);
troughGroup.add(topArrow);
const bottomArrow = new THREE.Mesh(new THREE.ConeGeometry(0.32, 0.9, 24), matCone);
bottomArrow.position.set(-3.6, 0.45, -0.15);
bottomArrow.rotation.x = Math.PI;
troughGroup.add(bottomArrow);

const xAxisLine = makeLine(graphGroup, matBlack, 'graph x-axis');
setLinePoints(xAxisLine, [localPoint(-7.2, 0, 0), localPoint(7.6, 0, 0)]);
const yAxisLine = makeLine(graphGroup, matBlack, 'graph y-axis');
setLinePoints(yAxisLine, [localPoint(0, 0, 0), localPoint(0, 19.6, 0)]);
const xAxisCone = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.65, 20), matCone);
xAxisCone.position.set(7.6, 0, 0);
xAxisCone.rotation.z = -Math.PI / 2;
graphGroup.add(xAxisCone);
const yAxisCone = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.65, 20), matCone);
yAxisCone.position.set(0, 19.6, 0);
graphGroup.add(yAxisCone);

const graphTickLine = makeLine(graphGroup, new THREE.LineBasicMaterial({ color: 0x777777, transparent: true, opacity: 0.45 }), 'graph ticks');
const graphWaterDepthLine = makeLine(graphGroup, matGraphWater, 'graph water depth line');
const graphBracketLine = makeLine(graphGroup, matGraphWater, 'graph chord width bracket');
const graphBracketTickLine = makeLine(graphGroup, matGraphWater, 'graph bracket ticks');

const rimLeftPoint = new THREE.Mesh(new THREE.SphereGeometry(0.35, 24, 12), matPoint);
rimLeftPoint.position.set(-6, 18, 0);
graphGroup.add(rimLeftPoint);
const rimRightPoint = new THREE.Mesh(new THREE.SphereGeometry(0.35, 24, 12), matPoint);
rimRightPoint.position.set(6, 18, 0);
graphGroup.add(rimRightPoint);

const tickPts = [];
for (let x = -6; x <= 6; x += 3) {
  tickPts.push(localPoint(x, -0.25, 0), localPoint(x, 0.25, 0));
}
for (let y = 3; y <= 18; y += 3) {
  tickPts.push(localPoint(-0.25, y, 0), localPoint(0.25, y, 0));
}
setLinePoints(graphTickLine, tickPts);

const profileCurveHandle = plotCurve3D('profile', {
  expr: '0.5*x^2',
  variables: ['x'],
  domain: [-6, 6],
  samples: 240,
  plane: 'xy',
  color: OUTLINE
});
scene.remove(profileCurveHandle.object);
profileCurveHandle.object.name = 'equation sampled graph curve';
graphGroup.add(profileCurveHandle.object);

let currentFn = (x) => 0.5 * x * x;
let currentExpr = '0.5*x^2';
let currentDepth = 9;
let currentLengthFt = 3;
let currentMode = '3D trough';
let lastIntersections = null;

function sampleProfile(fn, zValue) {
  const pts = [];
  const n = 180;
  for (let i = 0; i < n; i++) {
    const x = -6 + 12 * i / (n - 1);
    let y = NaN;
    try { y = fn(x); } catch { y = NaN; }
    if (Number.isFinite(y)) pts.push(localPoint(x, y, zValue));
  }
  return pts;
}

function findHorizontalIntersections(fn, h) {
  const roots = [];
  const n = 720;
  let prevX = -6;
  let prevY;
  try { prevY = fn(prevX) - h; } catch { prevY = NaN; }

  for (let i = 1; i <= n; i++) {
    const x = -6 + 12 * i / n;
    let y;
    try { y = fn(x) - h; } catch { y = NaN; }

    if (Number.isFinite(prevY) && Math.abs(prevY) < 1e-5) roots.push(prevX);
    if (Number.isFinite(prevY) && Number.isFinite(y) && prevY * y < 0) {
      const t = Math.abs(prevY) / (Math.abs(prevY) + Math.abs(y));
      roots.push(prevX + (x - prevX) * t);
    }
    if (Number.isFinite(y) && Math.abs(y) < 1e-5) roots.push(x);

    prevX = x;
    prevY = y;
  }

  roots.sort((a, b) => a - b);
  const unique = [];
  for (const r of roots) {
    if (r >= -6 - 1e-6 && r <= 6 + 1e-6 && (unique.length === 0 || Math.abs(r - unique[unique.length - 1]) > 0.04)) {
      unique.push(Math.max(-6, Math.min(6, r)));
    }
  }
  if (unique.length < 2) return null;
  return { left: unique[0], right: unique[unique.length - 1], roots: unique };
}

function updateWaterSurfaceGeometry(xL, xR, h, lenIn) {
  const old = waterSurfaceMesh.geometry;
  const geom = new THREE.BufferGeometry();
  const verts = new Float32Array([
    xL, h, 0,
    xR, h, 0,
    xR, h, lenIn,
    xL, h, lenIn
  ]);
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeVertexNormals();
  waterSurfaceMesh.geometry = geom;
  old?.dispose?.();
}

function updateTroughWireGeometry(fn, lenIn) {
  const xs = 31;
  const zs = 7;
  const vertices = [];
  const indices = [];
  for (let j = 0; j < zs; j++) {
    const z = lenIn * j / (zs - 1);
    for (let i = 0; i < xs; i++) {
      const x = -6 + 12 * i / (xs - 1);
      let y;
      try { y = fn(x); } catch { y = NaN; }
      if (!Number.isFinite(y)) y = 0;
      vertices.push(x, y, z);
    }
  }
  for (let j = 0; j < zs - 1; j++) {
    for (let i = 0; i < xs - 1; i++) {
      const a = j * xs + i;
      const b = a + 1;
      const c = a + xs;
      const d2 = c + 1;
      indices.push(a, b, d2, a, d2, c);
    }
  }
  const old = troughWireMesh.geometry;
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  troughWireMesh.geometry = geom;
  old?.dispose?.();
}

function updateGeometry() {
  const lenIn = currentLengthFt * 12;
  const h = currentDepth;
  const nearPts = sampleProfile(currentFn, 0);
  const farPts = sampleProfile(currentFn, lenIn);

  setLinePoints(nearProfileLine, nearPts);
  setLinePoints(farProfileLine, farPts);
  setLinePoints(nearTopChordLine, [localPoint(-6, 18, 0), localPoint(6, 18, 0)]);
  setLinePoints(farTopChordLine, [localPoint(-6, 18, lenIn), localPoint(6, 18, lenIn)]);
  setLinePoints(leftRimLine, [localPoint(-6, 18, 0), localPoint(-6, 18, lenIn)]);
  setLinePoints(rightRimLine, [localPoint(6, 18, 0), localPoint(6, 18, lenIn)]);
  setLinePoints(bottomSeamLine, [localPoint(0, 0, 0), localPoint(0, 0, lenIn)]);
  setLinePoints(farWidthBracketLine, [
    localPoint(-6, 19.25, lenIn), localPoint(6, 19.25, lenIn),
    localPoint(-6, 19.25, lenIn), localPoint(-6, 18.25, lenIn),
    localPoint(6, 19.25, lenIn), localPoint(6, 18.25, lenIn)
  ]);

  updateTroughWireGeometry(currentFn, lenIn);

  lastIntersections = findHorizontalIntersections(currentFn, h);
  const warn = document.getElementById('waterWarn');
  if (lastIntersections) {
    const xL = lastIntersections.left;
    const xR = lastIntersections.right;
    setLinePoints(waterNearChordLine, [localPoint(xL, h, -0.04), localPoint(xR, h, -0.04)]);
    setLinePoints(waterFarChordLine, [localPoint(xL, h, lenIn), localPoint(xR, h, lenIn)]);
    updateWaterSurfaceGeometry(xL, xR, h, lenIn);
    waterSurfaceMesh.visible = true;
    if (warn) warn.style.display = 'none';
  } else {
    setLinePoints(waterNearChordLine, []);
    setLinePoints(waterFarChordLine, []);
    waterSurfaceMesh.visible = false;
    if (warn) {
      warn.textContent = 'No two intersections with y = h on -6 ≤ x ≤ 6; water width is hidden.';
      warn.style.display = '';
    }
  }

  setLinePoints(graphWaterDepthLine, [localPoint(-6.8, h, 0.02), localPoint(6.8, h, 0.02)]);
  if (lastIntersections) {
    const xL = lastIntersections.left;
    const xR = lastIntersections.right;
    const yB = Math.min(18.8, h + 0.85);
    setLinePoints(graphBracketLine, [localPoint(xL, yB, 0.04), localPoint(xR, yB, 0.04)]);
    setLinePoints(graphBracketTickLine, [
      localPoint(xL, yB - 0.45, 0.04), localPoint(xL, yB + 0.45, 0.04),
      localPoint(xR, yB - 0.45, 0.04), localPoint(xR, yB + 0.45, 0.04)
    ]);
  } else {
    setLinePoints(graphBracketLine, []);
    setLinePoints(graphBracketTickLine, []);
  }
}

function updateReadout() {
  const h = currentDepth;
  const L = currentLengthFt;
  document.getElementById('waterDepthVal').textContent = `${fmt(h, 1)} in`;
  document.getElementById('troughLengthVal').textContent = `${fmt(L, 2)} ft`;

  let html = `h = ${fmt(h, 1)} in<br>L = ${fmt(L, 2)} ft = ${fmt(12 * L, 1)} in`;
  if (lastIntersections) {
    const width = lastIntersections.right - lastIntersections.left;
    const area = width * 12 * L;
    html += `<br>w(h) = ${fmt(width, 2)} in<br>A = w(h)·12L = ${fmt(area, 1)} in²`;
  } else {
    html += `<br>w(h) = —<br>A = —`;
  }
  document.getElementById('readout').innerHTML = html;
}

