function sampleProfile(fn, zValue) {
  const pts = [];
  const n = 180;
  for (let i = 0; i < n; i++) {
    const x = -6 + 12 * i / (n - 1);
    let y = NaN;
    try { y = fn(x); } catch { y = NaN; }
    if (Number.isFinite(y)) pts.push(localPoint(x, y, zValue));
  }
  return pts;
}

function findHorizontalIntersections(fn, h) {
  const roots = [];
  const n = 720;
  let prevX = -6;
  let prevY;
  try { prevY = fn(prevX) - h; } catch { prevY = NaN; }

  for (let i = 1; i <= n; i++) {
    const x = -6 + 12 * i / n;
    let y;
    try { y = fn(x) - h; } catch { y = NaN; }

    if (Number.isFinite(prevY) && Math.abs(prevY) < 1e-5) roots.push(prevX);
    if (Number.isFinite(prevY) && Number.isFinite(y) && prevY * y < 0) {
      const t = Math.abs(prevY) / (Math.abs(prevY) + Math.abs(y));
      roots.push(prevX + (x - prevX) * t);
    }
    if (Number.isFinite(y) && Math.abs(y) < 1e-5) roots.push(x);

    prevX = x;
    prevY = y;
  }

  roots.sort((a, b) => a - b);
  const unique = [];
  for (const r of roots) {
    if (r >= -6 - 1e-6 && r <= 6 + 1e-6 && (unique.length === 0 || Math.abs(r - unique[unique.length - 1]) > 0.04)) {
      unique.push(Math.max(-6, Math.min(6, r)));
    }
  }
  if (unique.length < 2) return null;
  return { left: unique[0], right: unique[unique.length - 1], roots: unique };
}

