  const vertices = [];
  const indices = [];
  for (let j = 0; j < zs; j++) {
    const z = lenIn * j / (zs - 1);
    for (let i = 0; i < xs; i++) {
      const x = -6 + 12 * i / (xs - 1);
      let y;
      try { y = fn(x); } catch { y = NaN; }
      if (!Number.isFinite(y)) y = 0;
      vertices.push(x, y, z);
    }
  }
  for (let j = 0; j < zs - 1; j++) {
    for (let i = 0; i < xs - 1; i++) {
      const a = j * xs + i;
      const b = a + 1;
      const c = a + xs;
      const d2 = c + 1;
      indices.push(a, b, d2, a, d2, c);
    }
  }
  const old = troughWireMesh.geometry;
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
