// @FIGURE_CODE_BEGIN
// near parabolic end → sampled black Line at the front cross-section
// far visible curved edge → sampled black Line for only the visible right half of the far parabolic end
// near and far top-width edges → black Lines across the 12 in open top
// side top rims → two black Lines along the 3 ft length
// lower vertex seam → black Line from near vertex to far vertex
// 18 in dimension → vertical black Line with two ConeGeometry arrowheads inside the near end
// 12 in dimension → short black LineSegments aligned just above the far top-width edge
// optional water chords → two blue Lines at y=h, hidden by default
// optional water surface → translucent blue rectangular Mesh, hidden by default
// graph axes → black Lines with ConeGeometry arrowheads
// graph parabola → plotCurve3D sampled from equation input
// graph water line and width bracket → blue Lines/LineSegments in cross-section mode
// graph rim endpoint markers → two black SphereGeometry points

const SCALE_IN = 0.085;
const OUTLINE = 0x111111;
const WATER = 0x4da3ff;
const WATER_DARK = 0x1f77cc;

const matBlack = new THREE.LineBasicMaterial({ color: OUTLINE });
const matDim = new THREE.LineBasicMaterial({ color: OUTLINE });
const matWater = new THREE.LineBasicMaterial({ color: WATER_DARK });
const matPoint = new THREE.MeshBasicMaterial({ color: OUTLINE });
const matCone = new THREE.MeshBasicMaterial({ color: OUTLINE });
const matWaterSurface = new THREE.MeshBasicMaterial({
  color: WATER,
  transparent: true,
  opacity: 0.24,
  side: THREE.DoubleSide,
  depthWrite: false
});

const troughGroup = new THREE.Group();
troughGroup.name = 'source-style parabolic trough outline';
troughGroup.scale.setScalar(SCALE_IN);
scene.add(troughGroup);

const graphGroup = new THREE.Group();
graphGroup.name = 'cross-section graph';
graphGroup.scale.setScalar(SCALE_IN);

function lp(x, y, z = 0) {
  return new THREE.Vector3(x, y, z);
}

function wp(x, y, z = 0) {
  return new THREE.Vector3(x * SCALE_IN, y * SCALE_IN, z * SCALE_IN);
}

function fmt(n, digits = 2) {
  if (!Number.isFinite(n)) return '—';
  return Number(n).toFixed(digits).replace(/\.?0+$/, '');
}

function makeLine(parent, material, name) {
  const line = new THREE.Line(new THREE.BufferGeometry(), material);
  line.name = name;
  parent.add(line);
  return line;
}

function makeSegments(parent, material, name) {
  const line = new THREE.LineSegments(new THREE.BufferGeometry(), material);
  line.name = name;
  parent.add(line);
  return line;
}

function setPoints(obj, pts) {
  const old = obj.geometry;
  obj.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old?.dispose?.();
  obj.visible = pts.length >= 2;
}

const nearProfileLine = makeLine(troughGroup, matBlack, 'near full parabolic end');
const farProfileLine = makeLine(troughGroup, matBlack, 'far visible right curved edge only');
const nearTopChordLine = makeLine(troughGroup, matBlack, 'near 12 inch top edge');
const farTopChordLine = makeLine(troughGroup, matBlack, 'far 12 inch top edge');
const leftRimLine = makeLine(troughGroup, matBlack, 'left upper rim');
const rightRimLine = makeLine(troughGroup, matBlack, 'right upper rim');
const bottomSeamLine = makeLine(troughGroup, matBlack, 'lower vertex seam');
const depthLine = makeLine(troughGroup, matDim, '18 inch vertical dimension');
const widthDim = makeSegments(troughGroup, matDim, '12 inch dimension aligned with far edge');
const waterNearLine = makeLine(troughGroup, matWater, 'optional near water chord');
const waterFarLine = makeLine(troughGroup, matWater, 'optional far water chord');
const waterSurface = new THREE.Mesh(new THREE.BufferGeometry(), matWaterSurface);
waterSurface.name = 'optional water surface';
troughGroup.add(waterSurface);

setPoints(depthLine, [lp(-3.85, 0.55, -18), lp(-3.85, 17.45, -18)]);
const topArrow = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.58, 22), matCone);
topArrow.position.set(-3.85, 17.45, -18);
troughGroup.add(topArrow);
const bottomArrow = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.58, 22), matCone);
bottomArrow.position.set(-3.85, 0.55, -18);
bottomArrow.rotation.x = Math.PI;
troughGroup.add(bottomArrow);

const xAxis = makeLine(graphGroup, matBlack, 'graph x-axis');
setPoints(xAxis, [lp(-7.2, 0, 0), lp(7.6, 0, 0)]);
const yAxis = makeLine(graphGroup, matBlack, 'graph y-axis');
setPoints(yAxis, [lp(0, 0, 0), lp(0, 19.6, 0)]);
const xCone = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.65, 20), matCone);
xCone.position.set(7.6, 0, 0);
xCone.rotation.z = -Math.PI / 2;
graphGroup.add(xCone);
const yCone = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.65, 20), matCone);
yCone.position.set(0, 19.6, 0);
graphGroup.add(yCone);

const tickLine = makeSegments(graphGroup, new THREE.LineBasicMaterial({ color: 0x777777, transparent: true, opacity: 0.45 }), 'graph ticks');
const tickPts = [];
for (let x = -6; x <= 6; x += 3) tickPts.push(lp(x, -0.25, 0), lp(x, 0.25, 0));
for (let y = 3; y <= 18; y += 3) tickPts.push(lp(-0.25, y, 0), lp(0.25, y, 0));
setPoints(tickLine, tickPts);

const graphWaterLine = makeLine(graphGroup, matWater, 'graph water depth line');
const graphBracket = makeLine(graphGroup, matWater, 'graph width bracket');
const graphBracketTicks = makeSegments(graphGroup, matWater, 'graph bracket ticks');

const rimL = new THREE.Mesh(new THREE.SphereGeometry(0.28, 22, 12), matPoint);
rimL.position.set(-6, 18, 0);
graphGroup.add(rimL);
const rimR = new THREE.Mesh(new THREE.SphereGeometry(0.28, 22, 12), matPoint);
rimR.position.set(6, 18, 0);
graphGroup.add(rimR);

const profileCurve = plotCurve3D('profileCurve', {
  expr: '0.5*x^2',
  variables: ['x'],
  domain: [-6, 6],
  samples: 240,
  plane: 'xy',
  color: OUTLINE
});
scene.remove(profileCurve.object);
profileCurve.object.name = 'cross-section parabola';
graphGroup.add(profileCurve.object);

let currentFn = x => 0.5 * x * x;
let currentExpr = '0.5*x^2';
let currentDepth = 9;
let currentLengthFt = 3;
let currentMode = '3D trough';
let showWater = false;
let lastIntersections = null;

function sampleProfile(fn, zValue, x0 = -6, x1 = 6, n = 220) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const x = x0 + (x1 - x0) * i / (n - 1);
    let y;
    try { y = fn(x); } catch { y = NaN; }
    if (Number.isFinite(y)) pts.push(lp(x, y, zValue));
  }
  return pts;
}

function findHorizontalIntersections(fn, h) {
  const roots = [];
  const n = 900;
  let px = -6;
  let py;
  try { py = fn(px) - h; } catch { py = NaN; }

  for (let i = 1; i <= n; i++) {
    const x = -6 + 12 * i / n;
    let y;
    try { y = fn(x) - h; } catch { y = NaN; }

    if (Number.isFinite(py) && Math.abs(py) < 1e-6) roots.push(px);
    if (Number.isFinite(py) && Number.isFinite(y) && py * y < 0) {
      const t = Math.abs(py) / (Math.abs(py) + Math.abs(y));
      roots.push(px + (x - px) * t);
    }
    if (Number.isFinite(y) && Math.abs(y) < 1e-6) roots.push(x);

    px = x;
    py = y;
  }

  roots.sort((a, b) => a - b);
  const unique = [];
  for (const r of roots) {
    if (r >= -6 - 1e-5 && r <= 6 + 1e-5 && (unique.length === 0 || Math.abs(r - unique[unique.length - 1]) > 0.035)) {
      unique.push(Math.max(-6, Math.min(6, r)));
    }
  }
  if (unique.length < 2) return null;
  return { left: unique[0], right: unique[unique.length - 1], roots: unique };
}

function setWaterSurface(xL, xR, h, zN, zF) {
  const old = waterSurface.geometry;
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute([
    xL, h, zN,
    xR, h, zN,
    xR, h, zF,
    xL, h, zF
  ], 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeVertexNormals();
  waterSurface.geometry = geom;
  old?.dispose?.();
}

function updateGeometry() {
  const lenIn = currentLengthFt * 12;
  const zN = -lenIn / 2;
  const zF = lenIn / 2;
  const h = currentDepth;

  setPoints(nearProfileLine, sampleProfile(currentFn, zN, -6, 6, 240));
  setPoints(farProfileLine, sampleProfile(currentFn, zF, 0, 6, 120));
  setPoints(nearTopChordLine, [lp(-6, 18, zN), lp(6, 18, zN)]);
  setPoints(farTopChordLine, [lp(-6, 18, zF), lp(6, 18, zF)]);
  setPoints(leftRimLine, [lp(-6, 18, zN), lp(-6, 18, zF)]);
  setPoints(rightRimLine, [lp(6, 18, zN), lp(6, 18, zF)]);
  setPoints(bottomSeamLine, [lp(0, 0, zN), lp(0, 0, zF)]);

  setPoints(depthLine, [lp(-3.85, 0.55, zN - 0.15), lp(-3.85, 17.45, zN - 0.15)]);
  topArrow.position.set(-3.85, 17.45, zN - 0.15);
  bottomArrow.position.set(-3.85, 0.55, zN - 0.15);

  const yDim = 19.05;
  setPoints(widthDim, [
    lp(-6, yDim, zF), lp(6, yDim, zF),
    lp(-6, yDim, zF), lp(-6, 18.1, zF),
    lp(6, yDim, zF), lp(6, 18.1, zF)
  ]);

  lastIntersections = findHorizontalIntersections(currentFn, h);
  const warn = document.getElementById('waterWarn');

  if (lastIntersections && showWater) {
    const xL = lastIntersections.left;
    const xR = lastIntersections.right;
    setPoints(waterNearLine, [lp(xL, h, zN - 0.035), lp(xR, h, zN - 0.035)]);
    setPoints(waterFarLine, [lp(xL, h, zF), lp(xR, h, zF)]);
    setWaterSurface(xL, xR, h, zN, zF);
    waterSurface.visible = true;
    if (warn) warn.style.display = 'none';
  } else {
    setPoints(waterNearLine, []);
    setPoints(waterFarLine, []);
    waterSurface.visible = false;
    if (warn && showWater && !lastIntersections) {
      warn.textContent = 'No two intersections with y = h on -6 ≤ x ≤ 6; water width is hidden.';
      warn.style.display = '';
    } else if (warn) {
      warn.style.display = 'none';
    }
  }

  setPoints(graphWaterLine, [lp(-6.8, h, 0.02), lp(6.8, h, 0.02)]);
  if (lastIntersections) {
    const xL = lastIntersections.left;
    const xR = lastIntersections.right;
    const yB = Math.min(18.85, h + 0.9);
    setPoints(graphBracket, [lp(xL, yB, 0.04), lp(xR, yB, 0.04)]);
    setPoints(graphBracketTicks, [
      lp(xL, yB - 0.45, 0.04), lp(xL, yB + 0.45, 0.04),
      lp(xR, yB - 0.45, 0.04), lp(xR, yB + 0.45, 0.04)
    ]);
  } else {
    setPoints(graphBracket, []);
    setPoints(graphBracketTicks, []);
  }
}

function updateReadout() {
  document.getElementById('waterDepthVal').textContent = `${fmt(currentDepth, 1)} in`;
  document.getElementById('troughLengthVal').textContent = `${fmt(currentLengthFt, 2)} ft`;
  let html = `h = ${fmt(currentDepth, 1)} in<br>L = ${fmt(currentLengthFt, 2)} ft = ${fmt(12 * currentLengthFt, 1)} in`;
  if (lastIntersections) {
    const width = lastIntersections.right - lastIntersections.left;
    html += `<br>w(h) = ${fmt(width, 2)} in`;
    if (showWater) html += `<br>water surface area = ${fmt(width * 12 * currentLengthFt, 1)} in²`;
  } else {
    html += `<br>w(h) = —`;
  }
  if (!showWater && currentMode === '3D trough') html += `<br><span style="color:#666">Water surface hidden to match the source diagram.</span>`;
  document.getElementById('readout').innerHTML = html;
}

let troughLabels = [];
let graphLabels = [];
let label18, label3ft, label12, labelEq, labelH, labelW, labelX, labelY, labelLeftPoint, labelRightPoint;

function setLabelVisibility(list, visible) {
  for (const e of list) e.div.style.visibility = visible ? 'visible' : 'hidden';
}

function updateLabelPositions() {
  if (!label18) return;
  const lenIn = currentLengthFt * 12;
  const zN = -lenIn / 2;
  const zF = lenIn / 2;

  label18.pos.copy(wp(-3.12, 9.3, zN - 0.1));
  label3ft.pos.copy(wp(-5.0, 19.7, 0));
  label3ft.div.innerHTML = `${fmt(currentLengthFt, 2)} ft`;
  label12.pos.copy(wp(0, 20.15, zF));
  label12.div.innerHTML = '12 in';

  labelEq.div.innerHTML = `y = ${currentExpr.replaceAll('*', '·').replaceAll('^2', '²')}`;
  labelEq.pos.copy(wp(3.55, 9.5, 0));
  labelH.div.innerHTML = `y = h = ${fmt(currentDepth, 1)}`;
  labelH.pos.copy(wp(-7.65, currentDepth, 0));

  if (lastIntersections) {
    const width = lastIntersections.right - lastIntersections.left;
    labelW.div.innerHTML = `w(h) = ${fmt(width, 2)} in`;
    labelW.pos.copy(wp((lastIntersections.left + lastIntersections.right) / 2, Math.min(19.65, currentDepth + 2.0), 0));
  }

  setLabelVisibility(troughLabels, currentMode === '3D trough');
  setLabelVisibility(graphLabels, currentMode === 'Cross-section graph');
  labelW.div.style.visibility = (currentMode === 'Cross-section graph' && lastIntersections) ? 'visible' : 'hidden';
}

function refitCamera() {
  if (currentMode === 'Cross-section graph') {
    setCameraView({
      projection: 'orthographic',
      azimuthDeg: 90,
      elevationDeg: 0,
      heightFraction: 0.8,
      target: [0, 0.78, 0]
    });
  } else {
    setCameraView({
      projection: 'oblique',
      obliqueAngleDeg: 190,
      depthScale: 0.58,
      heightFraction: 0.76,
      target: [0, 0.82, 0]
    });
  }
}

function setMode(mode) {
  currentMode = mode;
  const graph = mode === 'Cross-section graph';
  document.getElementById('mode3D').classList.toggle('active', !graph);
  document.getElementById('modeGraph').classList.toggle('active', graph);
  if (graph) {
    if (troughGroup.parent) scene.remove(troughGroup);
    if (!graphGroup.parent) scene.add(graphGroup);
  } else {
    if (graphGroup.parent) scene.remove(graphGroup);
    if (!troughGroup.parent) scene.add(troughGroup);
  }
  updateLabelPositions();
  refitCamera();
}

function applyControls() {
  currentDepth = parseFloat(document.getElementById('waterDepth').value);
  currentLengthFt = parseFloat(document.getElementById('troughLength').value);
  showWater = document.getElementById('showWater').checked;
  updateGeometry();
  updateReadout();
  updateLabelPositions();
  refitCamera();
}

updateGeometry();
refitCamera();

label18 = addLabel('18 in', wp(-3.12, 9.3, -18), { fontSize: '18px', color: '#111' });
label3ft = addLabel('3 ft', wp(-5.0, 19.7, 0), { fontSize: '18px', color: '#111' });
label12 = addLabel('12 in', wp(0, 20.15, 18), { fontSize: '18px', color: '#111' });
troughLabels = [label18, label3ft, label12];

labelEq = addLabel('y = x² / 2', wp(3.55, 9.5, 0), { fontSize: '15px', color: '#111', background: 'rgba(255,255,255,0.75)' });
labelH = addLabel('y = h = 9', wp(-7.65, 9, 0), { fontSize: '13px', color: '#1f77cc' });
labelW = addLabel('w(h)', wp(0, 11, 0), { fontSize: '13px', color: '#1f77cc', bold: true });
labelX = addLabel('x across width (in)', wp(4.35, -1.35, 0), { fontSize: '13px', color: '#111' });
labelY = addLabel('depth y (in)', wp(-2.1, 20.75, 0), { fontSize: '13px', color: '#111' });
labelLeftPoint = addLabel('(-6, 18)', wp(-6.7, 18.9, 0), { fontSize: '12px', color: '#111' });
labelRightPoint = addLabel('(6, 18)', wp(6.65, 18.9, 0), { fontSize: '12px', color: '#111' });
graphLabels = [labelEq, labelH, labelW, labelX, labelY, labelLeftPoint, labelRightPoint];

updateReadout();
updateLabelPositions();

registerInteractive(troughGroup, {
  title: 'Parabolic trough outline',
  tooltip: 'Source-style outline with the hidden far side omitted.',
  body: 'The default view keeps the sparse textbook drawing: black outline geometry and the three dimensions. Only the visible right-hand part of the far parabolic end is drawn, so the back side does not dominate the view.'
});
registerInteractive(waterSurface, {
  title: 'Optional water surface',
  tooltip: 'A removable aid, hidden by default.',
  body: 'When shown, the blue rectangle spans the horizontal chord y = h through the parabolic cross-section and extends along the length of the trough.'
});
registerInteractive(profileCurve.object, {
  title: 'Cross-section equation',
  tooltip: 'The graph mode shows the fitted parabola.',
  body: 'With vertex at the bottom and rim points (-6,18) and (6,18), the source dimensions give y = x²/2.'
});

document.getElementById('waterDepth').addEventListener('input', applyControls);
document.getElementById('troughLength').addEventListener('input', applyControls);
document.getElementById('showWater').addEventListener('change', applyControls);
